public final class PrimordialPhantom extends AbstractPhantom implements CooldownDiscipline.Participant {
    public static final Identifier ANIMATIONS=Identifier.fromNamespaceAndPath(Phantomism.MOD_ID,"entity/primordial_phantom");
    private static final int[] INTERVALS={240,240,480,320,600,480,2400};
    private static final String[] CLIPS={"starfall","strike","wing","shift","restoration","nova","domain","wave","conclusion"};
    private final int[] cooldowns=new int[7];
    private final Set<UUID> novaHits=new HashSet<>();
    private final PrimordialInsight insight=new PrimordialInsight();
    private UUID session=UUID.randomUUID(),orderedId,comboId;
    private int meleeTicks,actionTicks,comboTicks,wingTicks,wingCapacity,shiftFallTicks,restorationTicks,novaTicks,domainTicks;
    private Vec3 novaCenter,domainCenter;
    private boolean sessionOpen;
    public PrimordialPhantom(EntityType<? extends PrimordialPhantom> type,Level level){super(type,level);}
    public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,88).add(Attributes.ATTACK_DAMAGE,10).add(Attributes.ARMOR,14).add(Attributes.ARMOR_TOUGHNESS,6).add(Attributes.KNOCKBACK_RESISTANCE,.6D).add(Attributes.FOLLOW_RANGE,64).add(Attributes.MOVEMENT_SPEED,.25D).add(Attributes.FLYING_SPEED,.475D);}
    public static boolean checkSpawnRules(EntityType<PrimordialPhantom> type,ServerLevelAccessor accessor,EntitySpawnReason reason,BlockPos position,RandomSource random){ServerLevel level=accessor.getLevel();return PrimordialEncounterSpawner.habitat(level,position)&&level.getFluidState(position).isEmpty()&&level.getBlockState(position).getCollisionShape(level,position).isEmpty();}
    @Override protected Config.PhantomStats getConfiguredStats(){return Config.PRIMORDIAL_PHANTOM_STATS;}
    @Override public Identifier getPhantomAnimationResource(){return ANIMATIONS;}
    @Override public int getMaxSpawnClusterSize(){return 1;}
    @Override protected int getMeleeAttackCooldownTicks(){return 34;}
    @Override protected boolean preservesCombatTargetWhileRidden(){return true;}
    @Override public boolean isUltimateAnimationActive(){return domainTicks>0||super.isUltimateAnimationActive();}
    @Override public void travel(Vec3 input){if(getControllingPassenger()==null){travelFlying(input,(float)(getSpeed()*.09D));}else{super.travel(input);}}
    public UUID session(){return session;}
    public void visualStarted(){sessionOpen=true;}
    public boolean enabled(){return isAlive()&&!isRemoved()&&!isBaby()&&getOrder()!=Order.STAY&&getOrder()!=Order.RETURN_HOME&&(getTask()==PhantomAssignments.Task.NONE||getTask()==PhantomAssignments.Task.HUNT)&&(!isTame()||getOwner()!=null&&getOwner().isAlive()&&getOwner().level()==level());}
    public boolean ally(LivingEntity target){return target!=null&&target.isAlive()&&!target.isRemoved()&&target.level()==level()&&(target==this||isAlliedTo(target)||isTame()&&(target==getOwner()||target instanceof OwnableEntity owned&&Objects.equals(getOwnerReference(),owned.getOwnerReference())));}
    public boolean recipient(LivingEntity target){return enabled()&&isTame()&&ally(target)&&(target==this||target==getOwner()||target instanceof AbstractPhantom phantom&&phantom.isTame()&&Objects.equals(getOwnerReference(),phantom.getOwnerReference()));}
    private boolean recent(LivingEntity attacker,LivingEntity victim){return victim!=null&&(victim.getLastHurtByMob()==attacker&&victim.tickCount-victim.getLastHurtByMobTimestamp()<100||attacker.getLastHurtMob()==victim&&attacker.tickCount-attacker.getLastHurtMobTimestamp()<100||attacker instanceof Mob mob&&mob.getTarget()==victim);}
    private boolean provoked(LivingEntity target){return recent(target,this)||recent(target,getOwner());}
    public boolean safeEnemy(LivingEntity target){return target!=null&&target.isAlive()&&!target.isRemoved()&&target.level()==level()&&!target.isInvulnerable()&&!ally(target)&&!(target instanceof AbstractPhantom)&&!hasPassenger(target)&&!target.isPassengerOfSameVehicle(this)&&!isTargetSuppressed(target)&&!PhantomDuels.excludesObserver(this,target)&&!(target instanceof Player player&&(player.isCreative()||player.isSpectator()))&&!(target instanceof Mob mob&&VampireInfluence.isHypnotized(mob))&&!(target instanceof Creeper creeper&&(creeper.isIgnited()||creeper.getSwellDir()>0));}
    @Override protected boolean isSpeciesCombatTarget(LivingEntity target){if(!safeEnemy(target)){return false;}boolean explicit=target.getUUID().equals(orderedId)||PhantomDuels.pair(this,target)||provoked(target);if(target instanceof OwnableEntity owned&&owned.getOwnerReference()!=null){return explicit;}return explicit||isTame()&&target instanceof Enemy&&!(target instanceof NeutralMob)&&target.getType()!=EntityTypes.PIGLIN;}
    public boolean validTarget(LivingEntity target){return isSpeciesCombatTarget(target)&&getAssignments().permitsDefensivePursuit(target);}
    @Override protected boolean shouldHuntAutomatically(LivingEntity target,ServerLevel level){return validTarget(target)&&provoked(target);}
    @Override protected double getAutomaticTargetPriority(LivingEntity target){return(target.getType()==EntityTypes.EVOKER?-300:0)-Math.min(100,target.getMaxHealth())+distanceToSqr(target)*.01D;}
    @Override public void setCombatTarget(LivingEntity target){if(!safeEnemy(target)||!PhantomDuels.begin(this,target)){return;}orderedId=target.getUUID();super.setCombatTarget(target);}
    public boolean line(Vec3 start,Vec3 end){return Double.isFinite(start.lengthSqr())&&Double.isFinite(end.lengthSqr())&&isLoadedFlightBox(new AABB(start,end).inflate(.04D))&&level().clip(new ClipContext(start,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,this)).getType()==HitResult.Type.MISS;}
    public List<LivingEntity> enemies(ServerLevel level,Vec3 center,double radius,int maximum){return level.getEntitiesOfClass(LivingEntity.class,new AABB(center,center).inflate(radius),this::validTarget).stream().filter(target->target.distanceToSqr(center)<=radius*radius&&line(center.add(0,.4D,0),target.getEyePosition())).sorted(Comparator.comparingDouble(this::getAutomaticTargetPriority)).limit(maximum).toList();}
    public float damage(ServerLevel level,LivingEntity target,DamageSource source,float amount){if(!enabled()||!validTarget(target)||!Float.isFinite(amount)||amount<=0){return 0;}float before=target.getHealth()+target.getAbsorptionAmount();return target.hurtServer(level,source,amount)?Math.max(0,before-target.getHealth()-target.getAbsorptionAmount()):0;}
    @Override public boolean doHurtTarget(ServerLevel level,Entity target){if(meleeTicks>0||comboTicks>0||!(target instanceof LivingEntity enemy)||!getBoundingBox().inflate(.65D).intersects(enemy.getBoundingBox())||!line(getEyePosition(),enemy.getEyePosition())||damage(level,enemy,damageSources().mobAttack(this),(float)getAttributeValue(Attributes.ATTACK_DAMAGE))<=0){return false;}meleeTicks=34;action("strike",10);PrimordialVfx.emit(this,PrimordialVfx.IMPACT,null,enemy.position(),Vec3.ZERO,16,1);return true;}
    public boolean primordialStrike(ServerLevel level,LivingEntity target){if(!enabled()||cooldowns[1]>0||comboTicks>0||!validTarget(target)||!getBoundingBox().inflate(1.1D).intersects(target.getBoundingBox())||!line(getEyePosition(),target.getEyePosition())){return false;}comboId=target.getUUID();comboTicks=24;meleeTicks=34;cooldowns[1]=240;action("strike",24);return true;}
    private void combo(ServerLevel level){if(comboTicks<=0){return;}int elapsed=24- --comboTicks;if(!(level.getEntity(comboId) instanceof LivingEntity target)||!validTarget(target)||distanceToSqr(target)>3.5D*3.5D||!line(getEyePosition(),target.getEyePosition())){comboTicks=0;comboId=null;return;}if(elapsed==1||elapsed==12||elapsed==23){if(damage(level,target,damageSources().mobAttack(this),(float)getAttributeValue(Attributes.ATTACK_DAMAGE)*.6F)>0){PrimordialVfx.emit(this,PrimordialVfx.STRIKE,null,target.position(),target.position().subtract(position()),18,3);}}if(comboTicks==0){comboId=null;}}
    public boolean starfall(ServerLevel level,Vec3 aim){int interval=getControllingPassenger() instanceof Player?6:240;if(!enabled()||cooldowns[0]>240-interval||!Double.isFinite(aim.lengthSqr())||aim.lengthSqr()<.01D){return false;}Vec3 direction=aim.normalize(),muzzle=getEyePosition().add(direction.scale(.8D));if(!line(getEyePosition(),muzzle)){return false;}PrimordialStar star=PhantomismContent.PRIMORDIAL_STAR.get().create(level,EntitySpawnReason.TRIGGERED);if(star==null){return false;}star.setOwner(this);star.configure(session,false);star.setPos(muzzle);star.shoot(direction.x,direction.y,direction.z,2F,0);if(!level.addFreshEntity(star)){return false;}cooldowns[0]=240;action("starfall",12);PrimordialVfx.emit(this,PrimordialVfx.STAR,star,muzzle,direction,36,1);return true;}
    public void shatter(ServerLevel level,Vec3 center,Vec3 heading,UUID primary){List<LivingEntity> targets=enemies(level,center,8,16).stream().filter(target->!target.getUUID().equals(primary)).limit(3).toList();for(int index=0;index<3;index++){Vec3 direction=index<targets.size()?targets.get(index).getEyePosition().subtract(center).normalize():new Vec3(Math.cos(index*Math.PI*2/3),.12D,Math.sin(index*Math.PI*2/3)).normalize();Vec3 muzzle=center.add(direction.scale(.2D));if(!line(center,muzzle)){continue;}var shard=PhantomismContent.PRIMORDIAL_STAR.get().create(level,EntitySpawnReason.TRIGGERED);if(shard==null){continue;}shard.setOwner(this);shard.configure(session,true);shard.exclude(primary);shard.setPos(muzzle);shard.shoot(direction.x,direction.y,direction.z,1.4F,0);if(level.addFreshEntity(shard)){PrimordialVfx.emit(this,PrimordialVfx.STAR,shard,muzzle,direction,16,.4F);}}PrimordialVfx.emit(this,PrimordialVfx.SHATTER,null,center,heading,24,3);}
    @Override protected int getRiddenProjectileAbilityCooldownTicks(){return 6;}
    @Override protected boolean performRiddenProjectileAbility(ServerLevel level,Player rider){return starfall(level,rider.getViewVector(1));}
    public boolean activateRiddenDive(Player rider){if(!(level() instanceof ServerLevel level)||getControllingPassenger()!=rider||!isOwnedBy(rider)){return false;}LivingEntity target=enemies(level,position(),3.5D,16).stream().filter(enemy->rider.getViewVector(1).dot(enemy.getEyePosition().subtract(rider.getEyePosition()).normalize())>.25D).findFirst().orElse(null);return target!=null&&primordialStrike(level,target);}
    public LivingEntity ward(){return isTame()&&getOwner()!=null&&getOwner().isAlive()&&getOwner().level()==level()&&distanceToSqr(getOwner())<=20*20?getOwner():this;}
    public boolean creationWing(ServerLevel level){LivingEntity ward=ward();if(!enabled()||!isTame()||cooldowns[2]>0||enemies(level,ward.position(),16,1).isEmpty()){return false;}wingTicks=160;wingCapacity=12;cooldowns[2]=480;action("wing",20);PrimordialVfx.emit(this,PrimordialVfx.WING,ward,ward.position(),Vec3.ZERO,160,6);for(LivingEntity target:enemies(level,ward.position(),5,8)){PrimordialSupport.force(this,target,target.position().subtract(ward.position()),.4D);}return true;}
    public boolean wingActive(){return enabled()&&wingTicks>0&&wingCapacity>0;}
    public boolean spendWing(){if(!wingActive()){return false;}wingCapacity--;if(wingCapacity==0){wingTicks=0;}return true;}
    public boolean realityShift(ServerLevel level,LivingEntity threat){if(!enabled()||cooldowns[3]>0||isVehicle()||isPassenger()||!validTarget(threat)||distanceToSqr(threat)>12*12||!line(getEyePosition(),threat.getEyePosition())){return false;}double facing=Math.atan2(getZ()-threat.getZ(),getX()-threat.getX());for(int attempt=0;attempt<8;attempt++){double angle=facing+(attempt%2==0?1:-1)*(attempt+1)*Math.PI/8;Vec3 destination=position().add(Math.cos(angle)*7,1,Math.sin(angle)*7),delta=destination.subtract(position());AABB box=getBoundingBox().move(delta),swept=getBoundingBox().expandTowards(delta);if(box.minY<level.getMinY()+1||box.maxY>level.getMaxY()-1||!level.getWorldBorder().isWithinBounds(box)||!isLoadedFlightBox(swept)||!level.noCollision(this,swept)||level.containsAnyLiquid(swept)){continue;}Vec3 previous=position();teleportTo(destination.x,destination.y,destination.z);setDeltaMovement(Vec3.ZERO);fallDistance=0;getNavigation().stop();shiftFallTicks=60;cooldowns[3]=320;action("shift",18);PrimordialVfx.emit(this,PrimordialVfx.SHIFT,null,previous,delta,24,3);PrimordialVfx.emit(this,PrimordialVfx.ARRIVAL,this,position(),Vec3.ZERO,24,2);return true;}return false;}
    public boolean fallSafe(){return enabled()&&shiftFallTicks>0;}
    public boolean restoration(ServerLevel level){if(!enabled()||!isTame()||cooldowns[4]>0||level.getEntitiesOfClass(LivingEntity.class,getBoundingBox().inflate(20),target->recipient(target)&&distanceToSqr(target)<=20*20&&line(getEyePosition(),target.getEyePosition())&&(target.getHealth()<target.getMaxHealth()||target.getActiveEffects().stream().anyMatch(PrimordialSupport::cleanseable))).isEmpty()){return false;}restorationTicks=160;cooldowns[4]=600;action("restoration",24);PrimordialVfx.emit(this,PrimordialVfx.RESTORATION,this,position(),Vec3.ZERO,160,20);return true;}
    public boolean cosmicNova(ServerLevel level){if(!enabled()||cooldowns[5]>0||novaTicks>0||enemies(level,position(),12,2).size()<2){return false;}novaCenter=position();novaTicks=30;novaHits.clear();cooldowns[5]=480;action("nova",24);PrimordialVfx.emit(this,PrimordialVfx.NOVA,null,novaCenter,Vec3.ZERO,30,12);return true;}
    private void nova(ServerLevel level){if(novaTicks<=0){return;}int elapsed=30- --novaTicks;double radius=12*elapsed/30D;for(LivingEntity target:enemies(level,novaCenter,12,24)){if(!novaHits.contains(target.getUUID())&&novaHits.size()<12&&target.distanceToSqr(novaCenter)<=radius*radius){novaHits.add(target.getUUID());if(damage(level,target,damageSources().mobAttack(this),16)>0){PrimordialSupport.stun(this,target);}}else if(elapsed<10&&!novaHits.contains(target.getUUID())){PrimordialSupport.force(this,target,novaCenter.subtract(target.position()),.18D);}}if(novaTicks==0){novaCenter=null;novaHits.clear();}}
    public int domainTicks(){return domainTicks;}
    public Vec3 domainCenter(){return domainCenter;}
    public boolean primalDomain(ServerLevel level){if(!enabled()||cooldowns[6]>0||domainTicks>0){return false;}List<LivingEntity> crowd=enemies(level,position(),36,16);boolean emergency=isTame()&&getOwner()!=null&&getOwner().getHealth()<=getOwner().getMaxHealth()*.35F;if(crowd.size()<4&&!(emergency&&crowd.size()>=2)){return false;}domainCenter=position();domainTicks=300;cooldowns[6]=2400;action("domain",40);PrimordialVfx.emit(this,PrimordialVfx.DOMAIN,null,domainCenter,Vec3.ZERO,300,36);return true;}
    private void wave(ServerLevel level,float damage){for(LivingEntity target:enemies(level,domainCenter,36,16)){if(damage(level,target,damageSources().mobAttack(this),damage)>0){PrimordialVfx.emit(this,PrimordialVfx.JUDGMENT,target,target.position(),Vec3.ZERO,24,2);}}action("wave",20);}
    public float mitigation(LivingEntity target){if(!recipient(target)){return 0;}if(domainTicks>0&&target.distanceToSqr(domainCenter)<=36*36&&line(domainCenter.add(0,1,0),target.getEyePosition())){return .2F;}return distanceToSqr(target)<=16*16&&line(getEyePosition(),target.getEyePosition())?.1F:0;}
    public boolean empowers(AbstractPhantom ally,LivingEntity target){return enabled()&&domainTicks>0&&ally!=this&&recipient(ally)&&validTarget(target)&&ally.distanceToSqr(domainCenter)<=36*36&&target.distanceToSqr(domainCenter)<=36*36&&line(domainCenter.add(0,1,0),ally.getEyePosition());}
    @Override protected boolean prepareSpeciesCombatAction(ServerLevel level,LivingEntity target){if(!enabled()||!validTarget(target)){return true;}if(comboTicks>0||primordialStrike(level,target)){return true;}if(doHurtTarget(level,target)){return true;}return false;}
    @Override public void tick(){super.tick();if(!(level() instanceof ServerLevel level)){return;}for(int index=0;index<cooldowns.length;index++){if(cooldowns[index]>0){cooldowns[index]--;}}if(meleeTicks>0){meleeTicks--;}if(actionTicks>0){actionTicks--;}if(wingTicks>0){wingTicks--;}if(shiftFallTicks>0){shiftFallTicks--;}if(restorationTicks>0){restorationTicks--;}
        if(!enabled()){endPrimordial();return;}combo(level);nova(level);
        if(domainTicks>0){if(distanceToSqr(domainCenter)>64*64||!isLoadedFlightBox(new AABB(domainCenter,domainCenter).inflate(1))){endPrimordial();return;}int elapsed=300- --domainTicks;if(elapsed==120||elapsed==180){wave(level,12);}if(elapsed==240){wave(level,20);}if(domainTicks==0){PrimordialVfx.emit(this,PrimordialVfx.CONCLUSION,null,domainCenter,Vec3.ZERO,40,36);action("conclusion",24);domainCenter=null;}}
        if(tickCount%4==0&&wingActive()){PrimordialSupport.intercept(this,level);}
        if(tickCount%10==0){insight.tick(this,level);}
        if(tickCount%20==0){PrimordialSupport.maintain();if(validTarget(getTarget())){creationWing(level);primalDomain(level);if(domainTicks==0){cosmicNova(level);}if(getHealth()<=getMaxHealth()*.35F){realityShift(level,getTarget());}}restoration(level);if(restorationTicks>0||domainTicks>0){Vec3 center=domainTicks>0?domainCenter:position();double radius=domainTicks>0?36:20;for(LivingEntity target:level.getEntitiesOfClass(LivingEntity.class,new AABB(center,center).inflate(radius),this::recipient).stream().filter(target->target.distanceToSqr(center)<=radius*radius&&line(center.add(0,1,0),target.getEyePosition())).limit(32).toList()){PrimordialSupport.restore(this,target);}}if(domainTicks>0){int elapsed=300-domainTicks;for(LivingEntity target:enemies(level,domainCenter,36,24)){target.addEffect(new MobEffectInstance(MobEffects.SLOWNESS,40,0),this);target.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,40,0),this);if(elapsed>=40&&elapsed<=100){PrimordialSupport.force(this,target,domainCenter.subtract(target.position()),.15D);}}}else if(isTame()&&tickCount%40==0){PrimordialVfx.emit(this,PrimordialVfx.AURA,this,position(),Vec3.ZERO,44,3);}}
        if(!isVehicle()&&comboTicks==0&&tickCount%5==0&&validTarget(getTarget())&&distanceToSqr(getTarget())<=42*42&&line(getEyePosition(),getTarget().getEyePosition())){starfall(level,getTarget().getEyePosition().subtract(getEyePosition()));}
    }
    private void action(String clip,int ticks){actionTicks=ticks;visualStarted();triggerAnim("primordial",clip);}
    @Override public void registerControllers(AnimatableManager.ControllerRegistrar controllers){super.registerControllers(controllers);var controller=new AnimationController<PrimordialPhantom>("primordial",3,state->actionTicks>0?PlayState.CONTINUE:PlayState.STOP);for(String clip:CLIPS){controller.triggerableAnim(clip,RawAnimation.begin().thenPlay("animation.primordial."+clip));}controllers.add(controller);}
    @Override public InteractionResult mobInteract(Player player,InteractionHand hand){if(isAlive()&&!isTame()&&!player.isSpectator()&&player.getItemInHand(hand).is(PhantomismContent.HEART_OF_THE_WORLD.get())){if(!level().isClientSide()){if(!player.isCreative()){player.getItemInHand(hand).shrink(1);}tame(player);clearCombatTarget(true);level().broadcastEntityEvent(this,(byte)7);}return InteractionResult.SUCCESS;}return super.mobInteract(player,hand);}
    public void endPrimordial(){if(sessionOpen&&level() instanceof ServerLevel){PrimordialVfx.cancel(this);session=UUID.randomUUID();sessionOpen=false;}PrimordialSupport.release(this);insight.clear();orderedId=null;comboId=null;comboTicks=0;wingTicks=0;wingCapacity=0;shiftFallTicks=0;restorationTicks=0;novaTicks=0;domainTicks=0;actionTicks=0;novaCenter=null;domainCenter=null;novaHits.clear();}
    @Override public void clearCombatTarget(boolean suppress){super.clearCombatTarget(suppress);if(suppress&&cooldowns!=null){endPrimordial();}}
    @Override public void setOrder(Order order){super.setOrder(order);if(cooldowns!=null&&(order==Order.STAY||order==Order.RETURN_HOME)){endPrimordial();}}
    @Override public void setTask(PhantomAssignments.Task task){super.setTask(task);if(cooldowns!=null&&task!=PhantomAssignments.Task.NONE&&task!=PhantomAssignments.Task.HUNT){endPrimordial();}}
    @Override public void remove(RemovalReason reason){if(cooldowns!=null){endPrimordial();}super.remove(reason);}
    @Override protected void addAdditionalSaveData(ValueOutput output){super.addAdditionalSaveData(output);output.putInt("PrimordialMelee",meleeTicks);for(int index=0;index<cooldowns.length;index++){output.putInt("PrimordialCooldown"+index,cooldowns[index]);}}
    @Override protected void readAdditionalSaveData(ValueInput input){super.readAdditionalSaveData(input);endPrimordial();session=UUID.randomUUID();meleeTicks=Math.clamp(input.getIntOr("PrimordialMelee",0),0,34);for(int index=0;index<cooldowns.length;index++){cooldowns[index]=Math.clamp(input.getIntOr("PrimordialCooldown"+index,0),0,INTERVALS[index]);}}
    @Override public List<CooldownDiscipline.Slot> temporalCooldowns(){var slots=new ArrayList<CooldownDiscipline.Slot>();for(int index=0;index<6;index++){final int slot=index;slots.add(CooldownDiscipline.Slot.normal("primordial_"+CLIPS[index],INTERVALS[index],()->cooldowns[slot],value->cooldowns[slot]=value));}return List.copyOf(slots);}
}
